import gurobipy as gp
from gurobipy import GRB

def solve():
    weights = [6, 7, 8, 3, 2, 4, 5]
    capacity = 10
    n_items = len(weights)
    max_boxes = n_items

    env = None
    model = gp.Model(env=env)

    b = {}
    x = {}

    for k in range(1, max_boxes + 1):
        b[k] = model.addVar(type=GRB.BINARY, name=f"b_{k}")

    for i in range(n_items):
        for k in range(1, max_boxes + 1):
            x[(i, k)] = model.addVar(type=GRB.BINARY, name=f"x_{i}_{k}")

    # each item assigned to exactly one box
    for i in range(n_items):
        model.addConstr(gp.quicksum([x[(i, k)] for k in range(1, max_boxes + 1)]) == 1,
                         f"assign_{i}")

    # link assignment to box opening
    for i in range(n_items):
        for k in range(1, max_boxes + 1):
            model.addConstr(x[(i, k)] <= b[k], f"link_{i}_{k}")

    # capacity constraint per box
    for k in range(1, max_boxes + 1):
        expr = gp.quicksum([weights[i] * x[(i, k)] for i in range(n_items)])
        model.addConstr(expr <= capacity, f"cap_{k}")

    # objective: minimize number of boxes used
    obj = gp.quicksum([b[k] for k in range(1, max_boxes + 1)])
    model.setObjective(obj, GRB.MINIMIZE)

    model.optimize()

    if model.getStatus() == GRB.OPTIMAL:
        obj_val = int(round(model.ObjVal))
        print(f"FINAL_OBJECTIVE={obj_val}")

if __name__ == "__main__":
    solve()
