    widths = [d[0] for d in dims]
    heights = [d[1] for d in dims]

    n = len(widths)
    Lmax = n  # maximum possible levels

    m = gp.Model()
    x = {}
    H = {}
    for i in range(n):
        for l in range(Lmax):
            x[(i,l)] = m.addVar(lb=0, ub=1, vtype="Binary", name=f"x_{i}_{l}")
    for l in range(Lmax):
        H[l] = m.addVar(lb=0, name=f"H_{l}", vtype="Continuous")

    # assignment constraints
    for i in range(n):
        m.addConstr(gp.quicksum(x[(i,l)] for l in range(Lmax)) == 1, name=f"assign_{i}")

    # width capacity per level
    for l in range(Lmax):
        m.addConstr(gp.quicksum(widths[i] * x[(i,l)] for i in range(n)) <= 100, name=f"width_{l}")

    # height lower bounds
    for i in range(n):
        for l in range(Lmax):
            m.addConstr(H[l] >= heights[i] * x[(i,l)], name=f"height_bound_{i}_{l}")

