               ('H2', 'D1'): 4, ('H2', 'D2'): 3, ('H2', 'D3'): 6, ('H2', 'D4'): 5}

    # Model creation (using default environment; env can be passed if provided)
    model = gp.Model()

    # Variables x[i][h], y[h][d] continuous >=0
    x = {}
    for i in supplies:
        for h in hubs:
            x[(i, h)] = model.addVar(name=f"x_{i}_{h}", lb=0)

